        simp [ValidOnModel, ValidOnFrame, Satisfies];
        tauto;
      use ⟨Fin 2, λ x y => y = 1⟩;
      refine ⟨?_, ?_, ?_⟩;
      . simp [Transitive];
      . simp [Euclidean];
      . use (λ w _ => w = 0), 0;
        simp [Satisfies, Semantics.Realize];

